rule CobaltStrike_Shellcode {
    meta:
        description = "Detects encoded Cobalt Strike shellcode in memory dumps"
        author = "SOC_Team"
        reference = "MITRE ATT&CK T1055"
        date = "2026-04-09"
    strings:
        $a = { 60 00 00 00 48 89 E2 48 8B D1 BA }
        $b = { 49 89 C8 4D 89 C2 48 8B 0D ?? ?? ?? ?? }
    condition:
        all of them
}

